def find_path(graph, start, goal):
    # Initialize the stack for the depth-first search (DFS) and the found set
    stack = [(start, [start])]  # (current node, path)
    visited = set()
    found = False

    # Perform DFS
    while stack and not found:
        (node, path) = stack.pop()
        if node in visited:
            continue
        visited.add(node)
        if node == goal:
            found = True
        else:
            # Add the neighbors to the stack
            stack.extend( (neighbor, path + [neighbor]) for neighbor in graph[node] if neighbor not in visited )

    if found:
        return path
    else:
        return None
