def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None
    if start == goal:
        return [start]  # If start and goal are the same, we're done.

    # Initialize the stack for the recursive (or iterative) depth-first search
    stack = [(start, [start])]
    while stack:
        (node, path) = stack.pop()
        for next_node in graph[node]:
            if next_node not in path:  # Avoid cycles
                new_path = path + [next_node]
                if next_node == goal:
                    return new_path
                stack.append((next_node, new_path))
    return None
