def find_path(graph, start, goal):
    # A stack (using a list) for the recursive call
    path = []
    # A recursion stack for the recursive call
    stack = [(start, [start])]

    # Recursive function to find the path
    def recursive_find_path(node, path):
        path.append(node)
        if node == goal:
            return path
        for neighbor in graph.get(node, []):
            if neighbor not in path:
                new_path = recursive_find_path(neighbor, path.copy())
                if new_path:
                    return new_path
        path.pop()
        return None

    while stack:
        node, path = stack.pop()
        result = recursive_find_path(node, path)
        if result:
            return result
    return None
