def find_path(graph, start, goal):
    # A simple stack-based recursive path search
    def recursive_search(path, current_node, visited):
        if current_node == goal:
            return path

        visited.add(current_node)

        if current_node not in graph:
            return None

        for neighbor in graph[current_node]:
            if neighbor not in visited:
                new_path = recursive_search(path + [neighbor], neighbor, visited)
                if new_path is not None:
                    return new_path

        return None

    # Start the search
    return recursive_search([start], start, set())

