def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    # Initialize the stack for the recursive path search (using a recursive function)
    def recursive_search(stack, path, visited):
        (current_node, path) = stack.pop()
        visited.add(current_node)

        if current_node == goal:
            return path

        for next_node in graph[current_node]:
            if next_node not in visited:
                stack.append((next_node, path + [next_node]))

        if not stack:
            return None
        return recursive_search(stack, path, visited)

    # Start the recursive search with a stack containing the initial node
    stack = [(start, [start])]
    visited = set()

    return recursive_search(stack, [start], visited)
