    # Initialize the stack for the recursive stack (reverse) and the current path
    def dfs(x, path):
        if x == goal:
            return path
        if x not in graph:
            return None
        for neighbor in reversed(graph[x]):
            if neighbor not in path:
                result = dfs(neighbor, path + [neighbor])
                if result:
                    return result
        return None

